 * Tracks a position (line, column) while walking a source string one code
 * point at a time, applying the tab and line-feed column rules.
 */
export class Scanner {
  constructor(text) {
    this.chars = Array.from(text)
    this.pos = 0
    this.line = 1
    this.col = 1
  }

  peek(offset = 0) {
    return this.chars[this.pos + offset]
  }

  advance() {
    const c = this.chars[this.pos]
    this.pos++
    if (c === '\n') {
      this.line++
      this.col = 1
    } else if (c === '\t') {
      this.col = Math.floor((this.col - 1) / 4) * 4 + 5
    } else {
      this.col++
    }
    return c
  }

  /** The source text consumed since `start` (a saved `pos`). */
  slice(start) {
    return this.chars.slice(start, this.pos).join('')
  }
}

export class LexError extends Error {
  constructor(line, col, reason) {
    super(`${line}:${col}: ${reason}`)
    this.line = line
    this.col = col
    this.reason = reason
  }
}
"}

