const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const PUNCTS = [
  '==', '!=', '<=', '>=', '&&', '||', '->', '=>',
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.',
]

const isIdentStart = (c) => c !== undefined && /[A-Za-z_]/.test(c)
const isIdentPart = (c) => c !== undefined && /[A-Za-z0-9_]/.test(c)
const isDecDigit = (c) => c !== undefined && /[0-9]/.test(c)
const isWordChar = (c) => c !== undefined && /[A-Za-z0-9_]/.test(c)
const isHexDigit = (c) => c !== undefined && /[0-9a-fA-F]/.test(c)

function isBaseDigit(base, c) {
  if (c === undefined) return false
  if (base === 16) return /[0-9a-fA-F]/.test(c)
  if (base === 8) return /[0-7]/.test(c)
  if (base === 2) return /[01]/.test(c)
  return /[0-9]/.test(c)
}

/**
 * Consumes a run of base-`base` digits, allowing a single `_` between two
 * digits of the run. Returns the number of digits (not underscores) consumed.
 */
function consumeDigitRun(s, base) {
  let count = 0
  let sawDigit = false
  for (;;) {
    const c = s.peek()
    if (isBaseDigit(base, c)) {
      s.advance()
      count++
      sawDigit = true
      continue
    }
    if (c === '_' && sawDigit && isBaseDigit(base, s.peek(1))) {
      s.advance()
      sawDigit = false
      continue
    }
    break
  }
  return count
}

function scanIdent(s) {
  const line = s.line
  const col = s.col
  let text = ''
  while (isIdentPart(s.peek())) text += s.advance()
  const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
  return { line, col, kind, text }
}

function failNumber(s, line, col, startPos) {
  while (isWordChar(s.peek())) s.advance()
  throw new LexError(line, col, `invalid number ${s.slice(startPos)}`)
}

function scanNumber(s) {
  const line = s.line
  const col = s.col
  const startPos = s.pos

  const prefixChar = s.peek(1)
  if (s.peek() === '0' && prefixChar !== undefined && /[xXbBoO]/.test(prefixChar)) {
    const base = /[xX]/.test(prefixChar) ? 16 : /[bB]/.test(prefixChar) ? 2 : 8
    s.advance()
    s.advance()
    const count = consumeDigitRun(s, base)
    if (count === 0) failNumber(s, line, col, startPos)
  } else {
    consumeDigitRun(s, 10)
    if (s.peek() === '.' && isDecDigit(s.peek(1))) {
      s.advance()
      consumeDigitRun(s, 10)
    }
    if (s.peek() === 'e' || s.peek() === 'E') {
      const signLen = s.peek(1) === '+' || s.peek(1) === '-' ? 1 : 0
      if (isDecDigit(s.peek(1 + signLen))) {
        s.advance()
        if (signLen) s.advance()
        consumeDigitRun(s, 10)
      }
    }
  }

  if (isWordChar(s.peek())) failNumber(s, line, col, startPos)

  return { line, col, kind: 'number', text: s.slice(startPos) }
}

function scanString(s) {
  const line = s.line
  const col = s.col
  s.advance() // opening quote
  let value = ''
  for (;;) {
    const c = s.peek()
    if (c === undefined) throw new LexError(line, col, 'unterminated string')
    if (c === '"') {
      s.advance()
      break
    }
    if (c === '\n') throw new LexError(s.line, s.col, 'newline in string')
    if (c === '\\') {
      const bsLine = s.line
      const bsCol = s.col
      s.advance()
      const e = s.peek()
      if (e === undefined) throw new LexError(line, col, 'unterminated string')
      switch (e) {
        case 'n':
          s.advance()
          value += '\n'
          break
        case 't':
          s.advance()
          value += '\t'
          break
        case 'r':
          s.advance()
          value += '\r'
          break
        case '\\':
          s.advance()
          value += '\\'
          break
        case '"':
          s.advance()
          value += '"'
          break
        case '0':
          s.advance()
          value += '\0'
          break
        case 'x': {
          s.advance()
          const h1 = s.peek()
          const h2 = s.peek(1)
          if (isHexDigit(h1) && isHexDigit(h2)) {
            s.advance()
            s.advance()
            value += String.fromCharCode(parseInt(h1 + h2, 16))
          } else {
            throw new LexError(bsLine, bsCol, 'invalid escape \\x')
          }
          break
        }
        case 'u': {
          s.advance()
          if (s.peek() !== '{') throw new LexError(bsLine, bsCol, 'invalid escape \\u')
          s.advance()
          let hex = ''
          while (isHexDigit(s.peek())) hex += s.advance()
          if (hex.length === 0 || s.peek() !== '}') {
            throw new LexError(bsLine, bsCol, 'invalid escape \\u')
          }
          s.advance()
          const cp = parseInt(hex, 16)
          if (cp > 0x10ffff) throw new LexError(bsLine, bsCol, 'invalid escape \\u')
          value += String.fromCodePoint(cp)
          break
        }
        default:
          throw new LexError(bsLine, bsCol, `invalid escape \\${e}`)
      }
      continue
    }
    value += s.advance()
  }
  return { line, col, kind: 'string', value }
}

function scanRawString(s) {
  const line = s.line
  const col = s.col
  s.advance() // r
  s.advance() // opening quote
  let value = ''
  for (;;) {
    const c = s.peek()
    if (c === undefined) throw new LexError(line, col, 'unterminated string')
    if (c === '"') {
      s.advance()
      break
    }
    value += s.advance()
  }
  return { line, col, kind: 'rawstring', value }
}

function skipTrivia(s) {
  for (;;) {
    const c = s.peek()
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      s.advance()
      continue
    }
    if (c === '/' && s.peek(1) === '/') {
      s.advance()
      s.advance()
      while (s.peek() !== undefined && s.peek() !== '\n') s.advance()
      continue
    }
    if (c === '/' && s.peek(1) === '*') {
      const line = s.line
      const col = s.col
      s.advance()
      s.advance()
      let depth = 1
      while (depth > 0) {
        if (s.peek() === undefined) throw new LexError(line, col, 'unterminated block comment')
        if (s.peek() === '/' && s.peek(1) === '*') {
          s.advance()
          s.advance()
          depth++
          continue
        }
        if (s.peek() === '*' && s.peek(1) === '/') {
          s.advance()
          s.advance()
          depth--
          continue
        }
        s.advance()
      }
      continue
    }
    break
  }
}

function tryPunct(s) {
  for (const p of PUNCTS) {
    if (p.length === 2) {
      if (s.peek() === p[0] && s.peek(1) === p[1]) return p
    } else if (s.peek() === p[0]) {
      return p
    }
  }
  return null
}

/** Scans `source` into a flat array of `{ line, col, kind, text }` tokens. */
export function tokenize(source) {
  const s = new Scanner(source)
  const tokens = []
  for (;;) {
    skipTrivia(s)
    const c = s.peek()
    if (c === undefined) break

    if (c === '"') {
      const t = scanString(s)
      tokens.push({ line: t.line, col: t.col, kind: 'string', text: JSON.stringify(t.value) })
    } else if (c === 'r' && s.peek(1) === '"') {
      const t = scanRawString(s)
      tokens.push({ line: t.line, col: t.col, kind: 'rawstring', text: JSON.stringify(t.value) })
    } else if (isIdentStart(c)) {
      tokens.push(scanIdent(s))
    } else if (isDecDigit(c)) {
      tokens.push(scanNumber(s))
    } else {
      const line = s.line
      const col = s.col
      const p = tryPunct(s)
      if (p) {
        for (let k = 0; k < p.length; k++) s.advance()
        tokens.push({ line, col, kind: 'punct', text: p })
      } else {
        const ch = s.advance()
        throw new LexError(line, col, `unexpected character ${ch}`)
      }
    }
  }
  return tokens
}

export { LexError }
"}

